#!/usr/bin/env node
// Embeds the frozen Design templates (this folder) into templates.generated.ts so the compiled backend needs no runtime file access.
// Run: node src/fa4/email-templates/generate.js   (a unit test fails if the generated file drifts from the sources)
const fs = require("node:fs"); const path = require("node:path");
const dir = __dirname; const out = {};
for (const f of fs.readdirSync(dir).sort()) if (/\.(html|txt)$/.test(f)) out[f] = fs.readFileSync(path.join(dir, f), "utf8");
out["subjects.json"] = fs.readFileSync(path.join(dir, "subjects.json"), "utf8");
fs.writeFileSync(path.join(dir, "templates.generated.ts"), `// GENERATED by generate.js from the frozen FA4 Email Design v2 templates — do not edit.\nexport const TEMPLATE_FILES: Record<string, string> = ${JSON.stringify(out, null, 1)};\n`);
console.log("wrote", Object.keys(out).length, "files");
